1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    font: 16px/1.4 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
12	    background: #f5f5f4;
13	    color: #1c1917;
14	  }
15	  main {
16	    max-width: 32rem;
17	    margin: 3rem auto;
18	    padding: 0 1rem;
19	  }
20	  h1 { font-size: 1.5rem; margin: 0 0 1rem; }
21	  form { display: flex; gap: 0.5rem; }
22	  input {
23	    flex: 1;
24	    min-width: 0;
25	    padding: 0.6rem 0.75rem;
26	    font: inherit;
27	    border: 1px solid #d6d3d1;
28	    border-radius: 6px;
29	    background: #fff;
30	  }
31	  input:focus { outline: 2px solid #2563eb; outline-offset: -1px; border-color: transparent; }
32	  button {
33	    font: inherit;
34	    padding: 0.6rem 1rem;
35	    border: 0;
36	    border-radius: 6px;
37	    cursor: pointer;
38	  }
39	  .add { background: #2563eb; color: #fff; }
40	  .add:hover { background: #1d4ed8; }
41	  ul { list-style: none; margin: 1.25rem 0 0; padding: 0; }
42	  li {
43	    display: flex;
44	    align-items: center;
45	    gap: 0.75rem;
46	    padding: 0.6rem 0.75rem;
47	    background: #fff;
48	    border: 1px solid #e7e5e4;
49	    border-radius: 6px;
50	    margin-bottom: 0.5rem;
51	  }
52	  .text { flex: 1; overflow-wrap: anywhere; }
53	  .delete { background: transparent; color: #b91c1c; padding: 0.3rem 0.6rem; }
54	  .delete:hover { background: #fee2e2; }
55	  .empty { color: #78716c; margin-top: 1.25rem; }
56	</style>
57	</head>
58	<body>
59	<main>
60	  <h1>Todos</h1>
61	  <form id="todo-form" autocomplete="off">
62	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" aria-label="New todo">
63	    <button data-testid="todo-add" class="add" type="submit">Add</button>
64	  </form>
65	  <ul data-testid="todo-list"></ul>
66	  <p class="empty" hidden>No todos yet.</p>
67	</main>
68	<script>
69	(function () {
70	  var STORAGE_KEY = 'todos';
71	  var form = document.getElementById('todo-form');
72	  var input = document.querySelector('[data-testid="todo-input"]');
73	  var list = document.querySelector('[data-testid="todo-list"]');
74	  var empty = document.querySelector('.empty');
75	
76	  function load() {
77	    try {
78	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
79	      if (!Array.isArray(data)) return [];
80	      return data.filter(function (t) {
81	        return t && typeof t.id === 'string' && typeof t.text === 'string';
82	      });
83	    } catch (e) {
84	      return [];
85	    }
86	  }
87	
88	  function save() {
89	    try {
90	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
91	    } catch (e) {
92	      // Storage unavailable or full; keep working in memory.
93	    }
94	  }
95	
96	  function makeId() {
97	    if (window.crypto && typeof crypto.randomUUID === 'function') {
98	      try { return crypto.randomUUID(); } catch (e) { /* fall through */ }
99	    }
100	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
101	  }
102	
103	  function render() {
104	    list.textContent = '';
105	    todos.forEach(function (todo) {
106	      var li = document.createElement('li');
107	      li.setAttribute('data-testid', 'todo-item');
108	      li.setAttribute('data-id', todo.id);
109	
110	      var span = document.createElement('span');
111	      span.className = 'text';
112	      span.setAttribute('data-testid', 'todo-text');
113	      span.textContent = todo.text;
114	
115	      var del = document.createElement('button');
116	      del.type = 'button';
117	      del.className = 'delete';
118	      del.setAttribute('data-testid', 'todo-delete');
119	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
120	      del.textContent = 'Delete';
121	      del.addEventListener('click', function () { remove(todo.id); });
122	
123	      li.appendChild(span);
124	      li.appendChild(del);
125	      list.appendChild(li);
126	    });
127	    empty.hidden = todos.length > 0;
128	  }
129	
130	  function add(text) {
131	    text = text.trim();
132	    if (!text) return;
133	    todos.push({ id: makeId(), text: text, createdAt: Date.now() });
134	    save();
135	    render();
136	  }
137	
138	  function remove(id) {
139	    todos = todos.filter(function (t) { return t.id !== id; });
140	    save();
141	    render();
142	  }
143	
144	  var todos = load();
145	
146	  form.addEventListener('submit', function (e) {
147	    e.preventDefault();
148	    add(input.value);
149	    input.value = '';
150	    input.focus();
151	  });
152	
153	  render();
154	})();
155	</script>
156	</body>
157	</html>
