  li[data-completed="true"] .text { color: #a8a29e; text-decoration: line-through; }
""")
rep("""  </form>
  <ul""","""  </form>
  <div class="filters" role="group" aria-label="Filter todos">
    <button data-testid="filter-all" type="button" data-filter="all" aria-pressed="true">All</button>
    <button data-testid="filter-active" type="button" data-filter="active" aria-pressed="false">Active</button>
    <button data-testid="filter-completed" type="button" data-filter="completed" aria-pressed="false">Completed</button>
  </div>
  <ul""")
rep("""  var empty = document.querySelector('.empty');
""","""  var empty = document.querySelector('.empty');
  var filterButtons = document.querySelectorAll('[data-filter]');
  var filter = 'all';
""")
