      li.appendChild(span);""")
rep("""    empty.hidden = todos.length > 0;
  }""","""    if (todos.length === 0) {
      empty.textContent = 'No todos yet.';
    } else if (filter === 'active') {
      empty.textContent = 'No active todos.';
    } else {
      empty.textContent = 'No completed todos.';
    }
    empty.hidden = shown.length > 0;

    filterButtons.forEach(function (btn) {
      btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === filter ? 'true' : 'false');
    });
  }""")
rep("""createdAt: Date.now() });""","""completed: false, createdAt: Date.now() });""")
rep("""  var todos = load();
""","""  function toggle(id) {
    todos.forEach(function (t) {
      if (t.id === id) t.completed = !t.completed;
    });
    save();
    render();
  }

  var todos = load();

  filterButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      filter = btn.getAttribute('data-filter');
      render();
    });
  });
""")
