import { chromium } from 'playwright';
const b = await chromium.launch(); const p = await b.newPage();
const errs=[]; p.on('pageerror', e=>errs.push(e.message));
await p.goto('file:///Users/vmysla/src/product-tracebility-ab-testing/ab-study/arms/todo-rep-control-03/control/index.html');
const state = () => p.$$eval('[data-testid=todo-item]', els => els.map(e => e.querySelector('[data-testid=todo-text]').textContent + ':' + e.dataset.completed).join(' '));
for (const t of ['a','b','c','d']) { await p.fill('[data-testid=todo-input]', t); await p.click('[data-testid=todo-add]'); }
console.log('init     ', await state());
const toggleText = async t => p.locator('[data-testid=todo-item]', { hasText: t }).locator('[data-testid=todo-toggle]').click();
await toggleText('b'); await toggleText('a');
console.log('done b,a ', await state());
await p.click('[data-testid=filter-active]'); console.log('active   ', await state());
await p.click('[data-testid=filter-completed]'); console.log('completed', await state());
await p.click('[data-testid=filter-all]');
await toggleText('b'); console.log('undo b   ', await state());
await p.reload(); console.log('reload   ', await state());
await p.click('[data-testid=filter-completed]'); await toggleText('a'); console.log('undo a in completed view', await state(), await p.isVisible('.empty'));
console.log('errors', errs); await b.close();
EOF
